/* The floating Flows menu: each flow to try, with a start link and the inventory entries it touches. */
(function () {
  var W = window.W, e = W.esc;
  W.FLOWS = [
    { t: "1. Nothing is public before approval", r: "REQ-208, 084, 141, 143, 148", role: "visitor", go: "#/profile/harmattan-grid-energy", inv: ["V15", "A04", "V48"], s: ["As a visitor, open the link: 404.", "Switch to Reviewer (top bar), open Review queue, open Harmattan Grid Energy.", "Clear the scan flag, remove the unsourced field, tick the checklist, approve.", "Visit the page again (200) and check the Sitemap preview."] },
    { t: "2. Unpublish, 410 and purge", r: "REQ-091, 209", role: "editor", go: "#/admin/profiles", inv: ["A05", "V12", "A48", "V48"], s: ["Unpublish Palmline Media House with a reason.", "Open its public URL: 410 page.", "Check Sitemap preview and the Purge log.", "Restore it: 200 again."] },
    { t: "3. Bulk unpublish by filter, 410 and restore", r: "REQ-193, 209, 242, D-043, D-045", role: "reviewer", go: "#/admin/profiles?type=individual&origin=import", inv: ["A05", "A59", "V03", "V12", "V48", "A48"], s: ["The Profiles list is filtered to imported individuals. Read the match count, then press Unpublish these N\u2026, give a reason and confirm. Verified and Featured imports are included; customer-submitted Ngozi Balogun-Mensah is not.", "As a visitor open People: those profiles are gone. Open Tunde Achebe-Wanjala directly: 410. Check Sitemap preview and the Purge log.", "Switch to Editor and open the same list: there is no bulk panel (Reviewer and Administrator only, unless the Administrator grants it in WordPress). Back as Reviewer, under Recent bulk actions press Restore this batch: the URLs return 200.", "Try Group by Source and Group by Import batch, and the Sources screen (read-only)."] },
    { t: "4. Open nominations and the nominate journey", r: "REQ-106, 194, 195, 196, 267", role: "visitor", go: "#/nominate", inv: ["V22", "A28", "N01", "N02", "N12", "N03", "N04", "N05", "N10", "N11"], s: ["See the closed state: nominations are closed, with a link to the winners or nominees.", "Switch to Administrator, Nominations: press Open nominations (add a reason if you like). It is the only switch, and it is audited.", "Back on Nominate, fill step 1, then open the email outbox and click the single-use verification link (no account).", "Try evidence with a phone number; try nominating Tiderail Payments for the duplicate warning.", "Submit three times for the rate limit."] },
    { t: "5. Nominations: add a profile and email the nominee", r: "REQ-267, 202", role: "editor", go: "#/admin/nominations", inv: ["A28", "A29"], s: ["On Nominations press Add profile to nominations: pick a profile, a category, and a contact email (staff only). It starts as Nominated and Not live.", "Open the new nomination and press Send nomination email: it goes to the outbox, and the nomination records who sent it and when. Without a contact email the button is disabled.", "Use Remove nomination on a test nomination: confirm, and check the audit log entry."] },
    { t: "6. Offline judging: staff set Nominated or Winner and make it live", r: "REQ-038, 200, 202, 267", role: "editor", go: "#/admin/nominations", inv: ["A28", "A29", "V55", "V20"], s: ["Judging happens outside the site. Open NOM-0004: Stage Nominated, Status Not live.", "Press Make live on NOM-0001 and NOM-0004 (your name is recorded and audited).", "As a visitor, open Nominees and a nominee page: both are there. Switch back and make one Not live: it disappears."] },
    { t: "7. Winners: set the stage and make it live", r: "REQ-038, 267", role: "admin", go: "#/admin/nominations", inv: ["A28", "A29", "V21", "V20"], s: ["Open a nomination, set Stage to Winner and Status to Live, save.", "View Winners as a visitor: the winner is listed under the current edition.", "Back in the admin, Prepare winner email on the Winner (needs a contact email)."] },
    { t: "8. Staff edit a profile directly", r: "REQ-125, 188", role: "editor", go: "#/admin/profiles/b1", inv: ["A06", "A33"], s: ["Open Savanna Loop Agritech and use Edit this profile: change the city, give a reason, save.", "The public page changes at once. Check the revision history card.", "Switch to Administrator, Audit log: the edit is logged with actor and reason. There is no second-approver step."] },
    { t: "9. Enquiry to counted subscription", r: "REQ-177, 179, 022, 181", role: "visitor", go: "#/subscribe", inv: ["V24", "A12", "A14", "A15", "A16", "A02"], s: ["Send the enquiry form.", "Editor: Support inbox, read the enquiry.", "Administrator: Customers, New customer, then Register, fill every payment field and watch the counting check turn Yes.", "Administrator dashboard: the count rises."] },
    { t: "10. Sponsored story slot and its end", r: "REQ-155, 182, 263", role: "admin", go: "#/admin/sponsors", inv: ["A18", "V16", "V17"], s: ["Open Story sponsors: see the active slot and its dates.", "End the slot now: the Sponsored card disappears from the Stories page; the story stays published."] },
    { t: "11. A payment never changes a profile", r: "REQ-183, 184", role: "editor", go: "#/admin/profiles/b1", inv: ["A06", "A16"], s: ["Open the profile: no label can be set from a payment.", "As Administrator, confirm a payment for a profile in Register: its status does not change."] },
    { t: "12. Invited customer onboarding by single-use link", r: "REQ-013, 014, 084, 233", role: "visitor", go: "#/invite/demo", inv: ["O23", "O06", "O07", "O09", "O24", "A04"], s: ["Start my profile (no account), fill the form, save a draft, submit.", "Open the same link again: it has expired (single use).", "Switch to Reviewer; approve the profile. It goes public with the Reviewed on label."] },
    { t: "13. Role views: dashboard, left menu and read-only Sources", r: "REQ-235, 239, 240, 243", role: "reviewer", go: "#/admin", inv: ["A02", "A59", "A05", "O21"], s: ["As Reviewer: the dashboard shows only review and directory tiles, and the left menu has seven items.", "Open Sources: a read-only table (profiles, last import, errors, removals). Press Show these profiles, then Group by Import batch.", "As Reviewer, change the address to #/admin/import or #/admin/inbox: 403.", "Switch to Editor: the dashboard adds support and nominations counts; switch to Administrator: sprint target, revenue per stream and arrangements appear. Roles and capabilities are managed in WordPress."] },
    { t: "14. Correction, removal and report land in the Support inbox", r: "REQ-089, 156, 157, 158, 090", role: "visitor", go: "#/profile/halima-osei-danjuma", inv: ["V39", "V40", "V44", "A12", "A06"], s: ["Request removal for Halima Osei-Danjuma. Send a correction for Savanna Loop Agritech Report Palmline Media House.", "Switch to Editor, Support inbox: the items are typed (Correction, Removal, Report) with a status and a due countdown.", "Removal: Valid, hide + suppress (410 and the suppression list). Correction: Edit the profile and tick the item it resolves."] },
    { t: "15. Enquiry relay, rate limit and staff switch-off", r: "REQ-018, 122, 236", role: "visitor", go: "#/profile/ngozi-balogun-mensah", inv: ["V43", "A12", "A55", "V47"], s: ["Send an enquiry; send three for the rate limit.", "Switch to Editor and open the Support inbox: the enquiry is there, not with an owner.", "Open Profiles, Ngozi Balogun-Mensah, and switch enquiries off on request. The button disappears on the public page."] },
    { t: "16. Data request and cookies", r: "REQ-059, 062", role: "visitor", go: "#/data-rights", inv: ["V50", "A35", "V46"], s: ["Submit a request; staff close it.", "Change the cookie choice in the footer."] },
    { t: "17. Import with dry run", r: "REQ-009, 092, 147, 237", role: "admin", go: "#/admin/import", inv: ["A20", "A22"], s: ["Run the dry run on the sample CSV: an error row, a duplicate, a suppressed name and a blocked row for an unknown industry.", "Open Taxonomies > Industries and add Mining, then dry run again: the row is now valid.", "Import valid rows; see them in the queue."] },
    { t: "18. Create an event and link it from a story", r: "REQ-262, 264, 265", role: "editor", go: "#/admin/events", inv: ["A63", "A62", "V58", "V59", "V17", "V01"], s: ["On Events, add a new event: a title, a start date and time, a venue, an organiser, a summary and a registration link. Save it as published.", "Open Events as a visitor (the Events link in the header and footer): the event is listed under Upcoming events, with past events below. It is also in the Events section on the Home page when it is one of the next three.", "Open the event: the details block shows when, where, organiser and a link to the organiser's site. There is no payment or ticket button.", "On Stories, add a story and choose the event as its Related event. Open the story: a Related event card sits at the end, and the event page lists the story under Related stories. Unpublish the event on Events: the card and the event page disappear for the public."] },
    { t: "19. Sponsor a story with a paid slot", r: "REQ-263, 186, 199", role: "editor", go: "#/admin/sponsors", inv: ["A18", "V01", "V16", "V17"], s: ["On Story sponsors, add a slot: a sponsor, a published story, Home, and dates that include today. No amount is asked for.", "Open the Home page and the Stories page: the story leads as one slot labelled Sponsored by the sponsor, and the other stories stay in the same order.", "Try a second slot on the same page and dates: it is refused. Use End now: the label and slot are gone.", "Open Nominations and Scores: no sponsor or payment data appears there."] },
    { t: "20. Categories, then nominate a profile", r: "REQ-266, 267, 200", role: "editor", go: "#/admin/awards", inv: ["A30", "A28", "A29"], s: ["On Award categories, add a category to a group. It cannot be removed once a nomination uses it.", "On Nominations, press Add profile to nominations: pick a profile, choose the new category, add it.", "Open the new nomination, leave it Nominated, then press Make live on Nominations."] }
  ];
  W.flowsHtml = function () {
    return '<div id="flows" role="dialog" aria-label="Flows menu"><div class="row between"><h2 style="margin:0">Flows to try</h2><button type="button" class="btn alt sm" data-act="flows">Close</button></div><p class="small muted">Each flow switches the role for you and opens the first screen. Inventory IDs link to the screen list.</p><ol>' + W.FLOWS.map(function (f, i) {
      return "<li><strong>" + e(f.t) + '</strong> <span class="muted small">' + e(f.r) + '</span><ul class="small" style="padding-left:1.1rem;margin:4px 0">' + f.s.map(function (s) { return "<li>" + e(s) + "</li>"; }).join("") + '</ul><button type="button" class="btn sm" data-act="flowGo" data-arg="' + i + '">Start</button> <span class="small">' + f.inv.map(function (id) { return '<a href="#/inventory/' + e(id) + '">' + e(id) + "</a>"; }).join(" ") + "</span></li>";
    }).join("") + "</ol></div>";
  };
  W.act.flowGo = function (i) { var f = W.FLOWS[Number(i)]; W.S.role = f.role; W.ui.flows = false; W.save(); if (location.hash === f.go) W.render(); else location.hash = f.go; };
})();
